headers = {'Authorization': 'OAuth oauth_consumer_key="client_key", oauth_token="token", oauth_verifier="verifier", oauth_signature_method="PLAINTEXT", oauth_signature="signature", oauth_timestamp="1234567890", oauth_nonce="nonce", oauth_version="1.0"'}
